<h1>Online Store</h1><div class="grid"><?php foreach (($items ?: [['name'=>'Sacred products will appear here','description'=>'Admin can add products from dashboard.']]) as $item): ?><article class="panel"><h2><?= e($item['name']) ?></h2><p><?= e($item['description'] ?? '') ?></p><?php if(!empty($item['price'])): ?><p>₹<?= e((string)($item['offer_price'] ?: $item['price'])) ?></p><form method="post" action="/cart/add"><input type="hidden" name="slug" value="<?= e($item['slug']) ?>"><input type="hidden" name="qty" value="1"><button>Add to cart</button></form><?php endif; ?></article><?php endforeach; ?></div>
